        }
        catch (OperationCanceledException) when (startup.IsCancellationRequested)
        {
            await StopCoreAsync().ConfigureAwait(false);
            throw;
        }
        catch
        {
            await StopCoreAsync().ConfigureAwait(false);
            SetState(LifecycleState.Failed);
            throw;
        }
        finally
