            lock (_gate) { if (ReferenceEquals(_startup, startup)) _startup = null; }
            startup.Dispose();
            _transition.Release();
            StateChanged?.Invoke();
        }
    }

    private async Task StartCoreAsync(EngineConfig cfg, CancellationToken cancellation)
