        var psi = new ProcessStartInfo
        {
            FileName = _engineExe,
            WorkingDirectory = Path.GetDirectoryName(_engineExe)!,
            UseShellExecute = false, RedirectStandardOutput = true,
            RedirectStandardError = true, CreateNoWindow = true
        };
