            if (proc.HasExited)
                throw new InvalidOperationException($"Native engine exited during startup with code {proc.ExitCode} ({FormatExitCode(proc.ExitCode)}).{ExplainExitCode(proc.ExitCode)} Check the Logs tab.");
            string? mismatch = null;
