        if (Seed is < -1 or > 9007199254740991) throw new InvalidOperationException("Seed must be -1 (random) or a nonnegative JSON-safe integer.");
    }

    private static bool Near(double a, double b) => Math.Abs(a - b) <= 1e-9;
}

