    c.sampling.repeat_penalty = static_cast<float>(s->member_double("repeat_penalty", c.sampling.repeat_penalty));
    c.sampling.repeat_last_n = s->member_size("repeat_last_n", c.sampling.repeat_last_n);
    c.sampling.frequency_penalty = static_cast<float>(ReadFiniteNumber(s->find("frequency_penalty"), "sampling.frequency_penalty", c.sampling.frequency_penalty));
    c.sampling.presence_penalty = static_cast<float>(ReadFiniteNumber(s->find("presence_penalty"), "sampling.presence_penalty", c.sampling.presence_penalty));
  }
  c.sampling.Validate();
  if (c.reasoning_effort != "low" && c.reasoning_effort != "medium" && c.reasoning_effort != "xhigh")
    throw std::runtime_error("preferred reasoning_effort must be low, medium, or xhigh");
  if (c.context_lookup_min_draft > (c.context_lookup_policy == "fixed16" ? 16U : 6U))
    throw std::runtime_error("lookup minimum draft exceeds policy starting width");
  if (c.mtp_draft_vocabulary != "full" && c.mtp_draft_vocabulary != "latin")
    throw std::runtime_error("mtp_draft_vocabulary must be full or latin");
  if (c.mtp_draft_vocabulary == "latin" && c.sessions != 1)
    throw std::runtime_error("latin draft vocabulary requires sessions=1");
  if (c.model.empty()) throw std::runtime_error("config.model is required");
  if (c.context == 0 || c.draft_max == 0 || c.draft_max > 7)
    throw std::runtime_error("context/draft_max is invalid");
  if (c.draft_confidence < 0.0F || c.draft_confidence > 1.0F)
    throw std::runtime_error("draft_confidence must be from 0 to 1");
  if (c.mtp_proposal_mode != "halo_greedy" &&
      c.mtp_proposal_mode != "distribution")
    throw std::runtime_error("mtp_proposal_mode must be halo_greedy or distribution");
  if (c.prefill_batch < 128 || c.prefill_batch > 4096)
    throw std::runtime_error("prefill_batch must be from 128 to 4096");
  if (c.context_lookup &&
      (c.context_lookup_min_ngram < 2 ||
       c.context_lookup_max_ngram < c.context_lookup_min_ngram ||
       c.context_lookup_max_ngram > 32))
    throw std::runtime_error("context lookup settings are invalid");
  if (c.context_lookup_min_draft == 0 ||
      c.context_lookup_max_draft >
          gufo::models::qwen38_flash_next::kMaxContextLookupDraftTokens ||
      c.context_lookup_min_draft > c.context_lookup_max_draft)
    throw std::runtime_error("context lookup settings are invalid");
  if (!std::isfinite(c.memory_guard_min_available_gib) ||
      c.memory_guard_min_available_gib < 0.0 ||
      c.memory_guard_min_available_gib > 128.0)
    throw std::runtime_error("memory_guard_min_available_gib is invalid");
  if (c.sessions != 1)
    throw std::runtime_error("this Windows server currently supports sessions=1; Gufo batching remains in the engine for a later scheduler layer");
  return c;
}

gufo::models::qwen38_flash_next::SampledMtpProposalMode ParseMtpProposalMode(
    std::string_view value) {
  using Mode = gufo::models::qwen38_flash_next::SampledMtpProposalMode;
  return value == "distribution" ? Mode::kDistribution : Mode::kHaloGreedy;
}

std::string_view MtpProposalModeDisplay(std::string_view value) {
  return value == "distribution" ? "distribution (Gufo p/q)"
                                 : "halo-greedy (old-runtime compatible)";
}

gufo::tokenization::QwenReasoningEffort ParseEffort(std::string_view value) {
  if (value == "low")
    return gufo::tokenization::QwenReasoningEffort::kLow;
  if (value == "medium")
    return gufo::tokenization::QwenReasoningEffort::kMedium;
  if (value == "xhigh") return gufo::tokenization::QwenReasoningEffort::kXHigh;
  throw std::invalid_argument("reasoning_effort must be low, medium, xhigh, or off");
}

std::string_view EffortName(gufo::tokenization::QwenReasoningEffort effort) {
  using E = gufo::tokenization::QwenReasoningEffort;
  switch (effort) {
    case E::kLow: return "low";
    case E::kMedium: return "medium";
    case E::kXHigh: return "xhigh";
  }
  return "xhigh";
}

gufo::tokenization::ChatRole ParseRole(std::string_view role) {
  using R = gufo::tokenization::ChatRole;
  if (role == "system") return R::kSystem;
  if (role == "developer") return R::kDeveloper;
  if (role == "assistant") return R::kAssistant;
  if (role == "tool") return R::kTool;
  return R::kUser;
}

bool ParseContent(const Value* content, gufo::tokenization::ChatMessage* message,
                  gufo::core::ImageReadBudget* image_budget, std::string* error) {
  if (!content || content->is_null()) return true;
  if (content->is_string()) {
    message->content = content->get_str();
    return true;
  }
  if (!content->is_array()) {
    *error = "message content must be string/null/array";
    return false;
  }
  for (const auto& part : content->items()) {
    if (!part.is_object()) { *error = "content part must be object"; return false; }
    const auto type = part.member_str("type", "text");
    if (type == "text" || type == "input_text") {
      const auto* text = part.find("text");
      if (!text || !text->is_string()) { *error = "text content requires text"; return false; }
      message->content += text->get_str();
      continue;
    }
    if (type == "image_url") {
      const auto* obj = part.find("image_url");
      const auto* url = obj && obj->is_object() ? obj->find("url") : nullptr;
      if (!url || !url->is_string() || message->role != gufo::tokenization::ChatRole::kUser) {
        *error = "image_url requires a user message and URL";
        return false;
      }
      try {
        auto bytes = gufo::core::ReadImageUrl(url->get_str(), *image_budget);
        message->images.push_back({message->content.size(),
            std::make_shared<const std::vector<std::uint8_t>>(std::move(bytes))});
      } catch (const std::exception& e) {
        *error = e.what();
        return false;
      }
      continue;
    }
    *error = "unsupported content part type: " + type;
    return false;
  }
  return true;
}

std::string SavedAgentPrompt(const Config& cfg) {
  // Prompt edits are request settings, so they can be applied without
  // reloading the model or changing any engine/sampling settings.
  const auto& path = cfg.studio_config_path.empty() ? cfg.config_path : cfg.studio_config_path;
  if (path.empty() || !fs::exists(path)) return cfg.agent_prompt;
  const auto saved = gufo::json::parse(Slurp(path));
  const auto* prompt = saved.find("agent_prompt");
  if (!prompt) return cfg.agent_prompt;
  if (!prompt->is_string()) throw std::invalid_argument("saved agent_prompt must be a string");
  return prompt->get_str();
}

ChatInput ParseChat(const Value& body, const Config& cfg) {
  ChatInput out;
  out.enable_thinking = cfg.thinking;
  out.preserve_thinking = cfg.preserve_thinking;
  out.reasoning_effort = ParseEffort(cfg.reasoning_effort);

  if (const auto* kwargs = body.find("chat_template_kwargs"); kwargs && !kwargs->is_null()) {
    if (!kwargs->is_object())
      throw std::invalid_argument("chat_template_kwargs must be an object");
    out.enable_thinking = ReadBool(kwargs->find("enable_thinking"),
                                   "chat_template_kwargs.enable_thinking",
                                   out.enable_thinking);
    out.preserve_thinking = ReadBool(kwargs->find("preserve_thinking"),
                                     "chat_template_kwargs.preserve_thinking",
                                     out.preserve_thinking);
    out.add_vision_id = ReadBool(kwargs->find("add_vision_id"),
                                 "chat_template_kwargs.add_vision_id",
                                 out.add_vision_id);
    if (const auto* v = kwargs->find("reasoning_effort"); v && !v->is_null()) {
      if (!v->is_string())
        throw std::invalid_argument("chat_template_kwargs.reasoning_effort must be a string");
      if (v->get_str() == "off" || v->get_str() == "none") out.enable_thinking = false;
      else out.reasoning_effort = ParseEffort(v->get_str());
    }
  }
  if (const auto* v = body.find("reasoning_effort"); v && !v->is_null()) {
    if (!v->is_string())
      throw std::invalid_argument("reasoning_effort must be a string");
    if (v->get_str() == "off" || v->get_str() == "none") out.enable_thinking = false;
    else out.reasoning_effort = ParseEffort(v->get_str());
  }

  const auto* messages = body.find("messages");
  if (!messages || !messages->is_array() || messages->empty())
    throw std::invalid_argument("messages must be a non-empty array");
  std::string agent_prompt;
  if (const auto* prompt = body.find("agent_prompt"); prompt && !prompt->is_null()) {
    if (!prompt->is_string()) throw std::invalid_argument("agent_prompt must be a string");
    agent_prompt = prompt->get_str();
  }
  if (!agent_prompt.empty())
    out.messages.emplace_back(gufo::tokenization::ChatRole::kSystem, std::move(agent_prompt));
  gufo::core::ImageReadBudget budget;
  for (const auto& item : messages->items()) {
    if (!item.is_object()) throw std::invalid_argument("message must be an object");
    const auto role = item.member_str("role");
    if (role != "system" && role != "developer" && role != "user" && role != "assistant" && role != "tool")
      throw std::invalid_argument("invalid message role");
    gufo::tokenization::ChatMessage msg;
    msg.role = ParseRole(role);
    msg.name = item.member_str("name");
    msg.tool_call_id = item.member_str("tool_call_id");
    std::string error;
    if (!ParseContent(item.find("content"), &msg, &budget, &error))
      throw std::invalid_argument(error);
    if (const auto* r = item.find("reasoning_content"); r && r->is_string()) msg.thought = r->get_str();
    if (const auto* calls = item.find("tool_calls"); calls && calls->is_array()) {
      for (const auto& callv : calls->items()) {
        const auto* fn = callv.find("function");
        if (!fn || !fn->is_object()) continue;
        gufo::tokenization::ChatMessage::ToolCall call;
        call.id = callv.member_str("id");
        call.name = fn->member_str("name");
        const auto args_text = fn->member_str("arguments", "{}");
        Value args = gufo::json::parse(args_text);
        if (args.is_object()) {
          for (const auto& [name, val] : args.members()) {
            call.arguments.push_back({name, val.is_string() ? val.get_str() : val.dump(), val.is_string()});
          }
        }
        msg.tool_calls.push_back(std::move(call));
      }
    }
    out.messages.push_back(std::move(msg));
  }

  if (const auto* tools = body.find("tools"); tools && tools->is_array()) {
    for (const auto& item : tools->items()) {
      if (!item.is_object() || item.member_str("type") != "function") continue;
      const auto* fn = item.find("function");
      if (!fn || !fn->is_object()) continue;
      gufo::tokenization::ChatTool t;
      t.name = fn->member_str("name");
      t.description = fn->member_str("description");
      if (const auto* p = fn->find("parameters")) t.parameters_json = p->dump();
      t.definition_json = item.dump();
      if (!t.name.empty()) out.tools.push_back(std::move(t));
    }
  }
  if (const auto* choice = body.find("tool_choice"); choice && choice->is_string()) {
    if (choice->get_str() != "auto" && choice->get_str() != "required" && choice->get_str() != "none")
      throw std::invalid_argument("unsupported tool_choice");
    out.tool_required = choice->get_str() == "required";
    out.tool_none = choice->get_str() == "none";
  } else if (choice && choice->is_object()) {
    const auto* function = choice->find("function");
    const auto name = function ? function->member_str("name") : std::string{};
    if (choice->member_str("type") != "function" || name.empty())
      throw std::invalid_argument("invalid named tool_choice");
    std::erase_if(out.tools, [&](const auto& tool) { return tool.name != name; });
    out.tool_required = true;
  }
  if (out.tool_none) out.tools.clear();
  if (out.tool_required && out.tools.empty())
    throw std::invalid_argument("tool_choice requires an available function");
  return out;
}

gufo::sampling::SamplingConfig ParseSampling(const Value& body, const Config& cfg) {
  auto s = cfg.sampling;
  s.temperature = static_cast<float>(ReadFiniteNumber(body.find("temperature"), "temperature", s.temperature));
  s.top_p = static_cast<float>(ReadFiniteNumber(body.find("top_p"), "top_p", s.top_p));
  const auto top_k = ReadSize(body.find("top_k"), "top_k", static_cast<std::size_t>(s.top_k));
  if (top_k > static_cast<std::size_t>(std::numeric_limits<std::int32_t>::max()))
    throw std::invalid_argument("top_k exceeds the supported integer range");
  s.top_k = static_cast<std::int32_t>(top_k);
  s.min_p = static_cast<float>(ReadFiniteNumber(body.find("min_p"), "min_p", s.min_p));
  s.seed = ReadSeed(body.find("seed"), "seed", s.seed);
  s.repeat_penalty = static_cast<float>(ReadFiniteNumber(body.find("repeat_penalty"), "repeat_penalty", s.repeat_penalty));
  s.repeat_last_n = ReadSize(body.find("repeat_last_n"), "repeat_last_n", s.repeat_last_n);
  s.frequency_penalty = static_cast<float>(ReadFiniteNumber(body.find("frequency_penalty"), "frequency_penalty", s.frequency_penalty));
  s.presence_penalty = static_cast<float>(ReadFiniteNumber(body.find("presence_penalty"), "presence_penalty", s.presence_penalty));
  s.Validate();
  return s;
}

std::size_t MaxTokens(const Value& body, const Config& cfg) {
  const auto requested = [&]() {
    if (const auto* v = body.find("max_completion_tokens"); v && !v->is_null())
      return ReadSize(v, "max_completion_tokens", cfg.default_max_tokens);
    if (const auto* v = body.find("max_tokens"); v && !v->is_null())
      return ReadSize(v, "max_tokens", cfg.default_max_tokens);
    return cfg.default_max_tokens;
  }();
  if (requested == 0) throw std::invalid_argument("max_tokens must be a positive integer");
  return requested;
}

std::size_t EffectiveMaxTokens(std::size_t requested, std::size_t prompt_tokens,
                               std::size_t context_tokens) {
  if (prompt_tokens >= context_tokens) return 0;
  return std::min(requested, context_tokens - prompt_tokens);
}

std::int64_t ResolveActualSeed(std::int64_t requested_seed) {
  if (requested_seed >= 0) return requested_seed;
  std::random_device entropy;
  const std::uint64_t bits =
      (static_cast<std::uint64_t>(entropy()) << 32U) ^ entropy();
  return static_cast<std::int64_t>(bits & static_cast<std::uint64_t>(
                                              std::numeric_limits<std::int64_t>::max()));
}

ResolvedChatRequest ResolveChatRequest(const Value& body, const Config& cfg) {
  ResolvedChatRequest request;
  request.chat = ParseChat(body, cfg);
  request.sampling = ParseSampling(body, cfg);
  request.requested_max_tokens = MaxTokens(body, cfg);
  request.requested_seed = request.sampling.seed;
  request.sampling.seed = ResolveActualSeed(request.requested_seed);
  request.stream = ReadBool(body.find("stream"), "stream", false);
  request.profile = ReadBool(body.find("flashnext_profile"), "flashnext_profile", false);

  if (const auto* options = body.find("stream_options"); options && !options->is_null()) {
    if (!options->is_object())
      throw std::invalid_argument("stream_options must be an object");
    request.include_usage = ReadBool(options->find("include_usage"),
                                     "stream_options.include_usage", false);
  }
  return request;
}

std::vector<std::int32_t> ToI32(std::span<const gufo::tokenization::TokenId> src) {
  std::vector<std::int32_t> out;
  out.reserve(src.size());
  for (auto x : src) out.push_back(static_cast<std::int32_t>(x));
  return out;
}

std::vector<gufo::sampling::TokenId> ToSampler(std::span<const std::int32_t> src) {
  std::vector<gufo::sampling::TokenId> out;
  out.reserve(src.size());
  for (auto x : src) out.push_back(static_cast<gufo::sampling::TokenId>(x));
  return out;
}

std::string FormatFixed(double value, int digits) {
  std::ostringstream out;
  out << std::fixed << std::setprecision(digits) << value;
  return out.str();
}

